import { Array, Match as M, Schema as S } from "effect";
import { Command, Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { childAttributes, html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Combobox from "../../ui/combobox";

type City = "Kyiv" | "Oxford" | "Quito";

const CityCombobox = Combobox.Multi.create<City>();
const cities: readonly City[] = ["Kyiv", "Oxford", "Quito"];

// MODEL

export const Model = S.Struct({
  combobox: Combobox.Multi.Model,
});

export type Model = typeof Model.Type;

// MESSAGE

export const GotComboboxMessage = m("GotComboboxMessage", {
  message: Combobox.Message,
});

export const Message = S.Union([GotComboboxMessage]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => {
  const combobox = Combobox.Multi.init({
    id: "combobox-multi",
  });

  return [{ combobox }, []];
};

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotComboboxMessage: ({ message }) => {
        const [combobox, comboboxCommands] = CityCombobox.update(
          model.combobox,
          message
        );

        return [
          evo(model, { combobox: () => combobox }),
          Command.mapMessages(comboboxCommands, (message) =>
            GotComboboxMessage({ message })
          ),
        ];
      },
    })
  );

// VIEW

const filterCities = (inputValue: string): readonly City[] =>
  inputValue === ""
    ? cities
    : Array.filter(cities, (city) =>
        city.toLowerCase().includes(inputValue.toLowerCase())
      );

const viewInputs = (inputValue: string): Combobox.ViewInputs<City> => {
  const h = html<Message>();

  return {
    items: filterCities(inputValue),
    itemToConfig: (city, context) => ({
      className: Combobox.itemClassName,
      content: h.div(
        [h.Class("flex items-center gap-2")],
        [Combobox.selectedIcon(context.isSelected), h.span([], [city])]
      ),
    }),
    itemToValue: (city) => city,
    itemToDisplayText: (city) => city,
    inputAttributes: childAttributes([
      h.Class(Combobox.inputClassName),
      h.Placeholder("Search cities..."),
      h.AriaLabel("Cities"),
    ]),
    inputWrapperAttributes: childAttributes([
      h.Class(Combobox.inputWrapperClassName),
    ]),
    itemsAttributes: childAttributes([h.Class(Combobox.itemsClassName)]),
    backdropAttributes: childAttributes([h.Class(Combobox.backdropClassName)]),
    attributes: childAttributes([h.Class(Combobox.wrapperClassName)]),
    buttonContent: h.span([], ["v"]),
    buttonAttributes: childAttributes([h.Class(Combobox.buttonClassName)]),
    anchor: Combobox.defaultAnchor,
  };
};

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.div(
    [h.Class("space-y-3")],
    [
      h.div(
        [h.Class("flex flex-wrap gap-1.5")],
        Array.match(model.combobox.selectedItems, {
          onEmpty: () => [
            h.span(
              [h.Class(Combobox.emptyTagClassName)],
              ["No cities selected"]
            ),
          ],
          onNonEmpty: (selectedItems) =>
            selectedItems.map((item) =>
              h.span([h.Class(Combobox.tagClassName)], [item])
            ),
        })
      ),
      h.submodel({
        slotId: model.combobox.id,
        model: model.combobox,
        view: CityCombobox.view,
        viewInputs: viewInputs(model.combobox.inputValue),
        toParentMessage: (message) => GotComboboxMessage({ message }),
      }),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Combobox from "../../ui/combobox";
import * as ComboboxMultiExample from "./main";

const toParentMessage = (message: Combobox.Message) =>
  ComboboxMultiExample.GotComboboxMessage({ message });

const resolveComboboxMounts = () =>
  Scene.Mount.resolveAll(
    [
      Combobox.AnchorCombobox({
        buttonId: "combobox-multi-input-wrapper",
        anchor: Combobox.defaultAnchor,
      }),
      Combobox.CompletedAnchorCombobox(),
      toParentMessage,
    ],
    [
      Combobox.PortalComboboxBackdrop,
      Combobox.CompletedPortalComboboxBackdrop(),
      toParentMessage,
    ]
  );

const resolvePreventBlurMount = () =>
  Scene.Mount.resolve(
    Combobox.AttachComboboxPreventBlur,
    Combobox.CompletedAttachComboboxPreventBlur(),
    toParentMessage
  );

describe("Combobox Multi example", () => {
  test("filters and toggles city tags", () => {
    Scene.scene(
      {
        update: ComboboxMultiExample.update,
        view: ComboboxMultiExample.view,
      },
      Scene.with(ComboboxMultiExample.init()[0]),
      Scene.expect(Scene.placeholder("Search cities...")).toExist(),
      Scene.expect(Scene.text("No cities selected")).toExist(),
      resolvePreventBlurMount(),
      Scene.type(Scene.placeholder("Search cities..."), "ox"),
      resolveComboboxMounts(),
      Scene.expect(Scene.text("check")).not.toExist(),
      Scene.click(Scene.text("Oxford")),
      Scene.expect(Scene.text("Oxford")).toExist()
    );
  });
});
